interface View { show(value: number): void; }
class Screen implements View {
    shown = 0;
    show(value: number) { this.shown = value; }
}
class Presenter {
    constructor(private model: {count: number}, private view: View) {}
    click(delta: number) {
        this.model.count += delta;
        this.view.show(this.model.count);
    }
}
function demo() {
    const model = {count: 5}, screen = new Screen();
    new Presenter(model, screen).click(2);
    return model.count * 10 + screen.shown;
}

static class Example {
    interface IView { void Show(int value); }
    sealed class Model { public int Count = 5; }
    sealed class Screen : IView {
        public int Shown;
        public void Show(int value) { Shown = value; }
    }
    sealed class Presenter {
        readonly Model model; readonly IView view;
        public Presenter(Model m, IView v) { model = m; view = v; }
        public void Click(int delta) {
            model.Count += delta;
            view.Show(model.Count);
        }
    }
    public static int Demo() {
        var model = new Model(); var screen = new Screen();
        new Presenter(model, screen).Click(2);
        return model.Count * 10 + screen.Shown;
    }
}

class ViewModel {
    private count = 0;
    changed: (value: number) => void = () => {};
    get doubled() { return this.count * 2; }
    set(value: number) {
        this.count = value;
        this.changed(this.doubled);
    }
}
function demo() {
    const vm = new ViewModel();
    let shown = 0;
    vm.changed = value => { shown = value; };
    vm.set(6);
    return shown;
}

using System.ComponentModel;
static class Example {
    sealed class ViewModel : INotifyPropertyChanged {
        int count;
        public event PropertyChangedEventHandler? PropertyChanged;
        public int Doubled => count * 2;
        public void Set(int value) {
            count = value;
            PropertyChanged?.Invoke(this, new PropertyChangedEventArgs(nameof(Doubled)));
        }
    }
    public static int Demo() {
        var vm = new ViewModel(); int shown = 0;
        vm.PropertyChanged += (_, e) => {
            if (e.PropertyName == nameof(ViewModel.Doubled)) shown = vm.Doubled;
        };
        vm.Set(6);
        return shown;
    }
}

type Action = {type: "add"; delta: number};
function reduce(state: number, action: Action) { return state + action.delta; }
class Store {
    private state = 0;
    dispatch(action: Action) { this.state = reduce(this.state, action); }
    getState() { return this.state; }
}
function demo() {
    const store = new Store();
    store.dispatch({type: "add", delta: 2});
    const previous = store.getState();
    store.dispatch({type: "add", delta: 3});
    return previous * 10 + store.getState();
}

static class Example {
    readonly record struct Add(int Delta);
    static int Reduce(int state, Add action) => state + action.Delta;
    sealed class Store {
        public int State { get; private set; }
        public void Dispatch(Add action) { State = Reduce(State, action); }
    }
    public static int Demo() {
        var store = new Store();
        store.Dispatch(new Add(2)); int previous = store.State;
        store.Dispatch(new Add(3));
        return previous * 10 + store.State;
    }
}

